//! CRD YAML for every kind, as committed under `crds/`.

use kube::core::crd::CustomResourceExt;

use crate::{FleetRelease, LocalFleetRelease, Promotion, Shard, ShardConfig};

const HEADER: &str =
    "# Generated by `cargo run -p fleet-api --features crdgen --bin crdgen`. Do not edit.\n";

/// One generated CRD file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CrdFile {
    /// `<plural>.<group>.yaml`, e.g. `shards.fleet.believer.dev.yaml`.
    pub file_name: String,
    pub yaml: String,
}

/// The CRD YAML for every kind in the crate, in a stable order.
pub fn render_crds() -> Vec<CrdFile> {
    [
        ShardConfig::crd(),
        Shard::crd(),
        Promotion::crd(),
        FleetRelease::crd(),
        LocalFleetRelease::crd(),
    ]
    .into_iter()
    .map(|crd| {
        let name = crd.metadata.name.clone().expect("derived CRDs are named");
        let yaml = serde_yaml::to_string(&crd).expect("a CRD serializes to YAML");
        CrdFile {
            file_name: format!("{name}.yaml"),
            yaml: format!("{HEADER}{yaml}"),
        }
    })
    .collect()
}
